var DiningPhilosophers = function() {
    this.permits = 4;
    this.waiters = [];
    this.forks = Array.from({length: 5}, () => Promise.resolve());
};

DiningPhilosophers.prototype.acquireSeat = function() {
    if (this.permits > 0) { this.permits--; return Promise.resolve(); }
    return new Promise(res => this.waiters.push(res));
};

DiningPhilosophers.prototype.releaseSeat = function() {
    if (this.waiters.length) this.waiters.shift()();
    else this.permits++;
};

DiningPhilosophers.prototype.wantsToEat = function(philosopher, pickLeftFork, pickRightFork, eat, putLeftFork, putRightFork) {
    const l = philosopher, r = (philosopher + 1) % 5;
    const run = async () => {
        await this.acquireSeat();
        await this.forks[l].then(() => this.forks[r]).then(async () => {
            await pickLeftFork();
            await pickRightFork();
            await eat();
            await putLeftFork();
            await putRightFork();
        });
        this.releaseSeat();
    };
    const p = run();
    this.forks[l] = p.catch(() => {});
    this.forks[r] = p.catch(() => {});
    return p;
};
